import{_ as a,o as n,c as o,a2 as r}from"./chunks/framework.1C62pOns.js";const m=JSON.parse('{"title":"Documentación del Pro Agent Hub","description":"","frontmatter":{},"headers":[],"relativePath":"es/index.md","filePath":"es/index.md","lastUpdated":1787839708000}'),t={name:"es/index.md"};function s(i,e,d,c,l,p){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="documentacion-del-pro-agent-hub" tabindex="-1">Documentación del Pro Agent Hub <a class="header-anchor" href="#documentacion-del-pro-agent-hub" aria-label="Permalink to &quot;Documentación del Pro Agent Hub&quot;">​</a></h1><p>Pro Agent Hub es una plataforma para crear y operar asistentes de IA: agentes, equipos, bases de conocimiento, servicios MCP, workflows y aplicaciones web — todo configurado por pantalla, con Python donde la pantalla no alcanza.</p><h2 id="por-donde-empezar" tabindex="-1">Por dónde empezar <a class="header-anchor" href="#por-donde-empezar" aria-label="Permalink to &quot;Por dónde empezar&quot;">​</a></h2><p><strong><a href="/pro-agent-hub-installer/es/instalacao">Instalación</a></strong> — poner la plataforma en marcha en Linux, Windows o macOS.</p><p><strong><a href="/pro-agent-hub-installer/es/funcoes/">Referencia de funciones</a></strong> — lo que usted puede llamar en cada pantalla de código. La plataforma tiene <strong>siete lugares</strong> donde se escribe Python, y lo disponible difiere en cada uno: quien aprende <code>db_query(...)</code> en un Workflow y escribe lo mismo en una herramienta de Agente recibe <code>NameError</code>. Esta sección dice exactamente qué existe dónde.</p><h2 id="sobre-esta-documentacion" tabindex="-1">Sobre esta documentación <a class="header-anchor" href="#sobre-esta-documentacion" aria-label="Permalink to &quot;Sobre esta documentación&quot;">​</a></h2><p>La referencia de funciones se <strong>genera a partir del código fuente</strong> — de los mismos constructores de ámbito que la plataforma usa para ejecutar. Una operación nueva aparece aquí sin que nadie tenga que recordarla; una eliminada desaparece. No hay una lista escrita a mano para envejecer.</p><p>El manual de las pantallas (con imágenes) está en preparación.</p>',8)])])}const h=a(t,[["render",s]]);export{m as __pageData,h as default};
